import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import ItemList from 'flarum/common/utils/ItemList';
/**
 * The ways to contribute to Flarum, shared by the Contribute page and the homepage.
 */
export default class ContributionTypes extends Component {
  view() {
    return m("div", {
      className: "ContributePage-typeGrid"
    }, this.typeItems().toArray());
  }
  typeItems() {
    const items = new ItemList();
    items.add('code', this.type('fas fa-code', app.translator.trans('flarum-discuss.forum.contribute.type_code_title'), app.translator.trans('flarum-discuss.forum.contribute.type_code_desc')), 100);
    items.add('docs', this.type('fas fa-book', app.translator.trans('flarum-discuss.forum.contribute.type_docs_title'), app.translator.trans('flarum-discuss.forum.contribute.type_docs_desc')), 90);
    items.add('i18n', this.type('fas fa-language', app.translator.trans('flarum-discuss.forum.contribute.type_i18n_title'), app.translator.trans('flarum-discuss.forum.contribute.type_i18n_desc')), 80);
    items.add('financial', this.type('fas fa-heart', app.translator.trans('flarum-discuss.forum.contribute.type_financial_title'), app.translator.trans('flarum-discuss.forum.contribute.type_financial_desc')), 70);
    return items;
  }
  type(icon, title, description) {
    return m("div", {
      className: "ContributionType"
    }, m("div", {
      className: "ContributionType-icon"
    }, m(Icon, {
      name: icon
    })), m("h3", {
      className: "ContributionType-title"
    }, title), m("p", {
      className: "ContributionType-description"
    }, description));
  }
}
flarum.reg.add('flarum-discuss', 'forum/components/ContributionTypes', ContributionTypes);